import{Z as e,e as n,f as o,a0 as a}from"./chunks/framework.DmpHOl9T.js";const p=JSON.parse('{"title":"Constant Contact","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/email-marketing/constant-contact.md","filePath":"integrations/email-marketing/constant-contact.md","lastUpdated":1780377007000}'),i={name:"integrations/email-marketing/constant-contact.md"};function s(r,t,c,l,h,d){return n(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="constant-contact" tabindex="-1">Constant Contact <a class="header-anchor" href="#constant-contact" aria-label="Permalink to &quot;Constant Contact&quot;">​</a></h1><p>Connect Constant Contact to send newsletter sign-ups to your chosen mailing list. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Email Marketing</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Constant Contact as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-constant-contact-api" tabindex="-1">Step 2. Connect to the Constant Contact API <a class="header-anchor" href="#step-2-connect-to-the-constant-contact-api" aria-label="Permalink to &quot;Step 2. Connect to the Constant Contact API&quot;">​</a></h3><ol><li>Go to the <a href="https://developer.constantcontact.com/" target="_blank">Constant Contact</a> application manager, and login to your account.</li><li>In the top main menu, click on <strong>My Applications</strong>.</li><li>Click on the <strong>New Application</strong> button at top-right.</li><li>Enter a name in the popup window, and leave all other settings as-is. Click <strong>Save</strong>.</li><li>Click on the <strong>Edit</strong> button for the app you&#39;ve created.</li><li>In the <strong>Redirect URI</strong> field, enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>Copy the <strong>API Key</strong> from Constant Contact and paste in the <strong>API Key</strong> field in Formie.</li><li>Click the <strong>Generate Secret</strong> button, copy the <strong>App Secret</strong> and paste it into the <strong>App Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to Constant Contact, where you must approve Formie to access your Constant Contact account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Select the destination list and map its required email field to your form’s Email Address field. Map any additional fields your list requires using the variable picker. If you collect a newsletter opt-in, configure integration conditions so only visitors who choose it are sent.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Look up the test email in the selected list and check its mapped values and subscription state. If the provider requires confirmation, complete that step before expecting an active subscription.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',13)])])}const m=e(i,[["render",s]]);export{p as __pageData,m as default};
